    b+=l(400,162,400,200)+n(400,218,'امیہ')+l(400,226,400,254)+n(400,272,'خلفائے بنو امیہ')
    b+=l(260,162,260,290)+n(260,308,'عبدالمطلب')+l(260,316,260,336)+l(60,336,440,336)
    for x in (60,160,260,360,450): b+=l(x,336,x,352)
    b+=n(60,372,'ابولہب')+n(160,372,'عباس')+n(260,372,'عبداللہ')+n(360,372,'ابو طالب')+n(450,372,'امیر حمزہ')
    b+=l(160,380,160,420)+n(160,440,'خلفائے عباسیہ')+l(260,380,260,410)+n(260,432,'حضرت محمد رسول اللہ',13)+n(260,448,'خاتم النبیین ﷺ',13)+l(360,380,360,420)+n(360,440,'حضرت علی')
    return svg(500,470,'Family tree: Qusayy with sons Abd al-Dar, Abd Manaf and Abd al-Uzza; Abd Manaf with Abd Shams, Nawfal, Hashim and Muttalib; Abd Shams to Umayyah to the Umayyad caliphs; Hashim to Abdul Muttalib with sons Hamza, Abu Talib, Abdullah, Abbas and Abu Lahab; Abbas to the Abbasid caliphs; Abu Talib to Ali; Abdullah to the Prophet',b)
